"""Build a complete standalone script from the maintained modular sources."""

import ast
from pathlib import Path


def main():
    root = Path(__file__).resolve().parents[1]
    blocks = [
        '"""VelvetStream: complete standalone PySide6 application.\nGenerated by tools/bundle_source.py from the maintained modules.\nLaunch: python VelvetStreamStandalone.py\n"""\nfrom __future__ import annotations\n'
    ]
    for name in (
        "core",
        "runtime",
        "download_tasks",
        "services",
        "recognition",
        "fallback",
        "manual",
        "branding",
        "workers",
        "player",
        "ui",
    ):
        source = (root / "velvetstream" / f"{name}.py").read_text(encoding="utf-8")
        lines = source.splitlines(keepends=True)
        tree = ast.parse(source)
        remove = []
        for node in tree.body:
            if (
                isinstance(node, ast.ImportFrom) and (node.level or node.module == "__future__")
            ) or (
                isinstance(node, ast.Expr)
                and isinstance(node.value, ast.Constant)
                and isinstance(node.value.value, str)
            ):
                remove.append((node.lineno - 1, node.end_lineno))
        for start, end in reversed(remove):
            del lines[start:end]
        blocks.append(f"\n\n# ---- {name.upper()} ----\n" + "".join(lines))
    blocks.append(
        '\n\nif __name__ == "__main__":\n    multiprocessing.freeze_support()\n    configure_runtime()\n    raise SystemExit(main())\n'
    )
    output = root / "VelvetStreamStandalone.py"
    code = "".join(blocks)
    lines = code.splitlines(keepends=True)
    imports, from_imports, spans = {}, {}, []
    for node in ast.parse(code).body:
        if isinstance(node, ast.Import):
            for alias in node.names:
                imports[(alias.name, alias.asname)] = alias
            spans.append((node.lineno - 1, node.end_lineno))
        elif isinstance(node, ast.ImportFrom) and node.module != "__future__":
            group = from_imports.setdefault(node.module, {})
            for alias in node.names:
                group[(alias.name, alias.asname)] = alias
            spans.append((node.lineno - 1, node.end_lineno))
    for start, end in reversed(spans):
        del lines[start:end]

    def alias_text(alias):
        return alias.name + (" as " + alias.asname if alias.asname else "")

    import_text = "".join("import " + alias_text(alias) + "\n" for alias in imports.values())
    import_text += "".join(
        "from "
        + module
        + " import "
        + ", ".join(alias_text(alias) for alias in group.values())
        + "\n"
        for module, group in from_imports.items()
    )
    code = "".join(lines).replace(
        "from __future__ import annotations\n",
        "from __future__ import annotations\n\n" + import_text,
        1,
    )
    compile(code, str(output), "exec")
    output.write_text(code, encoding="utf-8")
    print(f"Built {output} ({len(code.splitlines())} lines)")


if __name__ == "__main__":
    main()
